function makeMarker(){markerGroup.clear();const t=targets[missionIndex];if(!t)return;markerRing=new THREE.Mesh(new THREE.TorusGeometry(1,.055,8,40),new THREE.MeshStandardMaterial({color:0xf0c46d,emissive:0x8b5420,emissiveIntensity:1.3}));markerRing.rotation.x=Math.PI/2;markerRing.position.set(t.x,.12,t.z);markerGroup.add(markerRing);markerBeam=new THREE.Mesh(new THREE.CylinderGeometry(.42,.1,3.8,16,1,true),new THREE.MeshBasicMaterial({color:0xe9b657,transparent:true,opacity:.15,side:THREE.DoubleSide,depthWrite:false}));markerBeam.position.set(t.x,2,t.z);markerGroup.add(markerBeam);const s=label('E  ·  '+t.name.toUpperCase(),t.x,3.7,t.z);markerGroup.add(s);}
let missionIndex=0,chapter=1;function updateMission(){const t=targets[missionIndex];document.querySelector('#objective').textContent=t?.name||'Historia completada';document.querySelector('#mission-copy').textContent=t?({1:'Explora el bloque y encuentra la manera de salir.',2:'La ciudad está alerta. Cambia tu apariencia y busca refugio.',3:'Una patrulla ha detectado el vehículo. Llega al punto seguro.'}[t.chapter]):'Nuevos capítulos llegarán pronto.';document.querySelector('#progress-fill').style.width=`${Math.min(100,missionIndex/7*100)}%`;document.querySelector('#progress-copy').textContent=`${missionIndex} / 7 OBJETIVOS`;document.querySelector('.chapter span').textContent=`CAPÍTULO 0${t?.chapter||3}`;document.querySelector('.chapter b').textContent=['','LA FUGA','LOS MÁS BUSCADOS','SIN SALIDA'][t?.chapter||3];document.querySelector('.minimap small').textContent=t?.chapter===1?'BLOQUE A':t?.chapter===2?'DISTRITO ESTE':'CENTRO';makeMarker();}
