// Character models
function character(outfit='prison'){const g=new THREE.Group();const torsoMat=outfit==='civil'?M.blue:M.shirt, legMat=outfit==='civil'?M.darkWall:M.pants;const torso= new THREE.Mesh(new THREE.BoxGeometry(.62,.85,.34),torsoMat);torso.position.y=1.2;torso.castShadow=true;g.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.22,16,12),M.skin);head.position.y=1.82;head.castShadow=true;g.add(head);const hair=new THREE.Mesh(new THREE.SphereGeometry(.225,16,8,0,Math.PI*2,0,Math.PI/2),M.black);hair.position.y=1.9;g.add(hair);const limbs=[];for(const x of [-.18,.18]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.13,.62,4,8),legMat);leg.position.set(x,.48,0);leg.castShadow=true;g.add(leg);limbs.push(leg);const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.105,.57,4,8),torsoMat);arm.position.set(x*2,1.25,0);arm.castShadow=true;g.add(arm);limbs.push(arm)}g.userData.limbs=limbs;g.userData.torso=torso;return g}
const player=character();scene.add(player);const shadow=new THREE.Mesh(new THREE.CircleGeometry(.5,24),new THREE.MeshBasicMaterial({color:0x0d1110,transparent:true,opacity:.42}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.018;player.add(shadow);
